command:
install -d -m 0750 /var/log/inventory
cat > /etc/rsyslog.d/20-inventory-collector.conf <<'ANTRIEB_EOF'
module(load="imtcp")
ruleset(name="inventory_remote") {
    if ($fromhost-ip == "10.100.56.11" and $programname == "inventory") then {
        action(type="omfile" file="/var/log/inventory/node2.log" createDirs="on" dirCreateMode="0750" fileCreateMode="0640")
        stop
    }
}
input(type="imtcp" port="514" ruleset="inventory_remote")
ANTRIEB_EOF
restorecon -RF /var/log/inventory /etc/rsyslog.d/20-inventory-collector.conf
ls -ldZ /var/log/inventory; sed -n '1,120p' /etc/rsyslog.d/20-inventory-collector.conf

